; =============== S U B R O U T I N E =======================================

; esi get_zbuff_pos(x@ecx, y@esi, z@ebp)
; pos = 4 * (x + NUM_TILES_X * y + NUM_TILES_X * NUM_TILES_Y * z)
get_zbuff_pos   proc near
                push eax
                imul esi, NUM_TILES_X
                mov  eax, ebp
                imul eax, NUM_TILES_X
                imul eax, NUM_TILES_Y
                add  esi, eax
                add  esi, ecx
                shl  esi, 2
                pop eax
                retn
get_zbuff_pos   endp


; =============== S U B R O U T I N E =======================================


set_volume_     proc near               ; CODE XREF: robots:loc_1D4B3?p
                                        ; main_+45E?p ...
                push ebx
                push ecx
                push edx
                push edi                
                push esi
                
                push eax                ; volume
                call set_volume
                pop eax

                pop esi
                pop edi
                pop edx
                pop ecx
                pop ebx
                retn ;eax
set_volume_     endp


; =============== S U B R O U T I N E =======================================


complete_missing_levels proc near
;Hex value  passed_level_in_zone
   ;00      none
   ;01      upper left
   ;02      upper right
   ;03      upper left and upper right
   ;04      lower left
   ;05      upper left and lower left
   ;06      upper right and lower left
   ;07      upper left, upper right, and lower left
   ;08      lower right
   ;09      upper left and lower right
   ;0A      upper right and lower right
   ;0B      upper left, upper right, and lower right
   ;0C      lower left and lower right
   ;0D      upper left, lower left, and lower right
   ;0E      upper right, lower left, and lower right
   ;0F      all
                pusha
                cmp active_map_screen_number, 4
                jne short loc_not_charlie_zone
                or passed_level_in_zone, 8
loc_not_charlie_zone: 
                cmp active_map_screen_number, 5
                jne short loc_not_delta_zone
                or passed_level_in_zone, 2
loc_not_delta_zone: 
                cmp active_map_screen_number, 6
                jne short loc_not_echo_zone
                or passed_level_in_zone, 9
loc_not_echo_zone: 
                cmp active_map_screen_number, 7
                jne short loc_not_foxtrot_zone
                or passed_level_in_zone, 10
loc_not_foxtrot_zone: 
                popa
                retn
complete_missing_levels endp


; =============== S U B R O U T I N E =======================================


short_wait proc near
                push    ebx
                xor     ebx, ebx
loc_10900: 
                call    sdl_events_
                inc     ebx
                cmp     ebx, eax
                jl      short loc_10900
                pop     ebx
                retn
short_wait endp


