; PS5 L1/R1 input: select the previous/next available weapon for the active robot.
; EDI is -1 for previous and +1 for next. Returns the 1-based slot, or -1
; when no weapon with ammunition is loaded.
bedlam2_ps5_cycle_weapon proc near
                push    ebx
                push    esi
                push    edi
                push    ebp
                mov     ebp, edi

                mov     edx, robot_offset
                add     edx, active_robot
                mov     eax, edx
                shl     eax, 2
                sub     eax, edx
                shl     eax, 4
                add     eax, edx
                shl     eax, 2
                mov     ebx, eax        ; per-robot weapon row, stride 0C4h

                movzx   esi, word ptr word_B2A76[ebx]
                xor     edi, edi
                mov     ecx, 7
loc_ps5_cycle_find_current:
                test    esi, 1
                jnz     short loc_ps5_cycle_current_found
                shr     esi, 1
                inc     edi
                dec     ecx
                jnz     short loc_ps5_cycle_find_current
                test    ebp, ebp
                js      short loc_ps5_cycle_no_current_previous
                mov     edi, 6          ; next scan begins at slot zero
                jmp     short loc_ps5_cycle_scan_start
loc_ps5_cycle_no_current_previous:
                xor     edi, edi        ; previous scan begins at slot six

loc_ps5_cycle_current_found:
loc_ps5_cycle_scan_start:
                mov     edx, 7
loc_ps5_cycle_scan:
                test    ebp, ebp
                js      short loc_ps5_cycle_previous
                inc     edi
                cmp     edi, 7
                jl      short loc_ps5_cycle_candidate
                xor     edi, edi
                jmp     short loc_ps5_cycle_candidate

loc_ps5_cycle_previous:
                dec     edi
                cmp     edi, 0
                jge     short loc_ps5_cycle_candidate
                mov     edi, 6

loc_ps5_cycle_candidate:
                mov     eax, edi
                lea     eax, [eax+eax*2]
                shl     eax, 2          ; each weapon record occupies 0Ch bytes
                add     eax, ebx
                cmp     word ptr weapon_ammo_pl2[eax+2], 0
                jz      short loc_ps5_cycle_next
                cmp     weapon_ammo[eax], 0
                jz      short loc_ps5_cycle_next

                mov     ecx, edi
                mov     eax, 1
                shl     eax, cl
                mov     word ptr word_B2A76[ebx], ax
                mov     sidebar_update_timer, 2
                mov     eax, edi
                inc     eax
                jmp     short loc_ps5_cycle_done

loc_ps5_cycle_next:
                dec     edx
                jnz     short loc_ps5_cycle_scan
                mov     eax, -1

loc_ps5_cycle_done:
                pop     ebp
                pop     edi
                pop     esi
                pop     ebx
                retn
bedlam2_ps5_cycle_weapon endp


; PS5 D-pad left/right: select the previous/next living squad robot.
; EDI is -1 for previous and +1 for next. Returns the 1-based robot slot,
; or -1 when no living squad member is available.
bedlam2_ps5_cycle_robot proc near
                push    ebx
                push    ecx
                push    edx
                push    esi
                push    edi
                push    ebp
                mov     ebp, edi
                mov     esi, robots_available
                test    esi, esi
                jle     short loc_ps5_robot_none
                mov     ebx, active_robot
                mov     ecx, esi

loc_ps5_robot_scan:
                test    ebp, ebp
                js      short loc_ps5_robot_previous
                inc     ebx
                cmp     ebx, esi
                jl      short loc_ps5_robot_candidate
                xor     ebx, ebx
                jmp     short loc_ps5_robot_candidate

loc_ps5_robot_previous:
                dec     ebx
                cmp     ebx, 0
                jge     short loc_ps5_robot_candidate
                lea     ebx, [esi-1]

loc_ps5_robot_candidate:
                mov     edi, robot_offset
                add     edi, ebx
                mov     eax, edi
                shl     eax, 2
                sub     eax, edi
                shl     eax, 4
                add     eax, edi        ; robot id = (robot_offset + slot) * 49
                cmp     robot_exist[eax*4], 0
                jnz     short loc_ps5_robot_selected
                dec     ecx
                jnz     short loc_ps5_robot_scan
                jmp     short loc_ps5_robot_none

loc_ps5_robot_selected:
                mov     active_robot, ebx
                mov     sidebar_update_timer, 2
                mov     dead_screen_scale, 0
                mov     dead_timer_in_MP_mode, 0
                mov     eax, ebx
                inc     eax
                jmp     short loc_ps5_robot_done

loc_ps5_robot_none:
                mov     eax, -1

loc_ps5_robot_done:
                pop     ebp
                pop     edi
                pop     esi
                pop     edx
                pop     ecx
                pop     ebx
                retn
bedlam2_ps5_cycle_robot endp


; PS5 Square input: resume camera tracking on the active robot.
bedlam2_ps5_center_view proc near
                push    eax
                mov     viewport_not_on_robot_timer, 0
                mov     dead_screen_scale, 0
                mov     dead_timer_in_MP_mode, 0
                mov     screen_x_pos, 0
                mov     screen_y_pos, 0
                mov     screen_z_pos, 0
                pop     eax
                xor     eax, eax
                retn
bedlam2_ps5_center_view endp

                end
